import unittest
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import allocate, fmt, parse_amount, parse_currency, parse_positive, to_base


class ParseTest(unittest.TestCase):
    def test_parse_amount_accepts(self):
        self.assertEqual(parse_amount("45"), Decimal("45.00"))
        self.assertEqual(parse_amount("45.5"), Decimal("45.50"))
        self.assertEqual(str(parse_amount("45.50")), "45.50")

    def test_parse_amount_rejects(self):
        for bad in ["0", "-3", "1.234", "abc", "", "NaN", "Infinity", "1e3", " 5", "0.00"]:
            with self.subTest(bad=bad), self.assertRaises(KittyError):
                parse_amount(bad)

    def test_parse_positive(self):
        self.assertEqual(parse_positive("0.923456", "rate"), Decimal("0.923456"))
        for bad in ["0", "-1", "nan", "inf", "x", "1e2"]:
            with self.subTest(bad=bad), self.assertRaises(KittyError):
                parse_positive(bad, "rate")

    def test_parse_currency(self):
        self.assertEqual(parse_currency("usd"), "USD")
        for bad in ["US", "USDX", "U1D", ""]:
            with self.subTest(bad=bad), self.assertRaises(KittyError):
                parse_currency(bad)


class FormatTest(unittest.TestCase):
    def test_fmt(self):
        self.assertEqual(fmt(Decimal("20.7")), "20.70")
        self.assertEqual(fmt(Decimal("-20.7")), "-20.70")
        self.assertEqual(fmt(Decimal("-0.00")), "0.00")
        self.assertEqual(fmt(Decimal("0")), "0.00")

    def test_to_base(self):
        self.assertEqual(to_base(Decimal("45.00"), Decimal("0.92")), Decimal("41.40"))
        self.assertEqual(to_base(Decimal("0.05"), Decimal("0.5")), Decimal("0.03"))  # half-up


class AllocateTest(unittest.TestCase):
    def test_allocate_equal_three(self):
        r = allocate(Decimal("10.00"), [("A", Decimal(1)), ("B", Decimal(1)), ("C", Decimal(1))])
        self.assertEqual(list(r.items()),
                         [("A", Decimal("3.34")), ("B", Decimal("3.33")), ("C", Decimal("3.33"))])

    def test_allocate_leftover_follows_list_order_not_remainder(self):
        r = allocate(Decimal("10.00"), [("A", Decimal(1)), ("B", Decimal(2))])
        self.assertEqual(r, {"A": Decimal("3.34"), "B": Decimal("6.66")})
        r = allocate(Decimal("10.00"), [("B", Decimal(2)), ("A", Decimal(1))])
        self.assertEqual(r, {"B": Decimal("6.67"), "A": Decimal("3.33")})

    def test_allocate_exact_weights_reproduce_values(self):
        r = allocate(Decimal("41.40"), [("A", Decimal("30")), ("B", Decimal("15"))])
        self.assertEqual(r, {"A": Decimal("27.60"), "B": Decimal("13.80")})

    def test_allocate_sums_to_total(self):
        w = [("A", Decimal("33.33")), ("B", Decimal("33.33")), ("C", Decimal("33.34"))]
        self.assertEqual(sum(allocate(Decimal("0.07"), w).values()), Decimal("0.07"))


if __name__ == "__main__":
    unittest.main()
