from decimal import Decimal as D

from kitty.ledger import settle


class SettleTest(unittest.TestCase):
    def test_settle_largest_pairs(self):
        b = {"A": D("30"), "B": D("-10"), "C": D("-20")}
        self.assertEqual(settle(b), [("C", "A", D("20")), ("B", "A", D("10"))])

    def test_settle_ties_alphabetical_ignoring_case(self):
        b = {"Zoe": D("10"), "bob": D("10"), "Cy": D("-20")}
        self.assertEqual(settle(b), [("Cy", "bob", D("10")), ("Cy", "Zoe", D("10"))])
        b = {"Al": D("20"), "dee": D("-10"), "Ben": D("-10")}
        self.assertEqual(settle(b), [("Ben", "Al", D("10")), ("dee", "Al", D("10"))])

    def test_settle_partial_payments(self):
        b = {"A": D("25"), "B": D("5"), "C": D("-18"), "D": D("-12")}
        self.assertEqual(settle(b), [("C", "A", D("18")), ("D", "A", D("7")), ("D", "B", D("5"))])

    def test_settle_even(self):
        self.assertEqual(settle({"A": D("0"), "B": D("0")}), [])

    def test_settle_does_not_modify_input(self):
        b = {"A": D("5"), "B": D("-5")}
