        self.ok("expense", "add", "Cara", "0.10", "gum")
        balances = json.loads(self.ok("balances"))
        self.assertEqual(list(balances), ["Alice", "Bob", "Cara"])
        self.assertEqual(sum(D(v) for v in balances.values()), D("0"))

    def test_member_remove_refused_after_payment(self):
        self.ok("member", "add", "Cara")
        self.ok("payment", "add", "Cara", "Bob", "1")
        self.fails("member", "remove", "Cara")


if __name__ == "__main__":
    unittest.main()
